<template>
  <div class="page">
    <div class="coupon-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>优惠券管理</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="name" label="优惠券名称" min-width="180" />
            <el-table-column prop="amount" label="面额" min-width="110" />
            <el-table-column prop="threshold" label="使用门槛" min-width="120" />
            <el-table-column prop="stock" label="库存" min-width="100" />
            <el-table-column prop="used" label="已使用" min-width="100" />
            <el-table-column prop="validity" label="有效期" min-width="220" />
            <el-table-column prop="tag" label="状态" min-width="100">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column label="操作" min-width="110">
              <template #default="scope">
                <el-button
                  size="small"
                  :type="scope.row.tag === '已停用' ? 'success' : 'danger'"
                  @click="handleToggle(scope.row.name)"
                >
                  {{ scope.row.tag === '已停用' ? '启用' : '停用' }}
                </el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="coupon-manage__pagination-wrap">
        <div class="totalnum">
          <h3>优惠券统计</h3>
          <p>当前共 {{ tableData.length }} 张优惠券</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import { ElMessage } from 'element-plus'

const currentPage = ref(1)
const pageSize = ref(6)

const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

const tagType = (tag) => {
  const map = {
    '发放中': 'success',
    '已停用': 'danger',
    '已过期': 'info',
  }
  return map[tag] || 'info'
}

const handleToggle = (name) => {
  const row = tableData.value.find((item) => item.name === name)
  if (!row) return
  row.tag = row.tag === '已停用' ? '发放中' : '已停用'
  ElMessage.success(`优惠券「${name}」已${row.tag === '发放中' ? '启用' : '停用'}`)
}

const tableData = ref([
  {
    name: '新人立减券',
    amount: '¥5.00',
    threshold: '满 20 可用',
    stock: 1000,
    used: 320,
    validity: '2024-01-01 ~ 2024-06-30',
    tag: '发放中',
  },
  {
    name: '满减券',
    amount: '¥10.00',
    threshold: '满 50 可用',
    stock: 800,
    used: 210,
    validity: '2024-01-01 ~ 2024-12-31',
    tag: '发放中',
  },
  {
    name: '双十一大额券',
    amount: '¥30.00',
    threshold: '满 200 可用',
    stock: 500,
    used: 480,
    validity: '2023-11-01 ~ 2023-11-11',
    tag: '已过期',
  },
  {
    name: '会员专享券',
    amount: '¥15.00',
    threshold: '满 100 可用',
    stock: 0,
    used: 600,
    validity: '2024-03-01 ~ 2024-09-30',
    tag: '已停用',
  },
  {
    name: '周末特惠券',
    amount: '¥8.00',
    threshold: '满 40 可用',
    stock: 1200,
    used: 150,
    validity: '2024-04-01 ~ 2024-10-31',
    tag: '发放中',
  },
  {
    name: '第四期满减券',
    amount: '¥20.00',
    threshold: '满 150 可用',
    stock: 400,
    used: 90,
    validity: '2024-05-01 ~ 2024-12-31',
    tag: '发放中',
  },
])
</script>

